import unittest

from sms.errors import GatewayTimeout, InvalidNumber, RateLimited
from sms.gateway import SmsGateway
from sms.otp import send_otp
from sms.retry import call_with_retry


class TopOfRange:
    """Deterministic 'random': always picks the upper bound, so delays equal the backoff ceiling."""

    def uniform(self, low, high):
        return high


class Script:
    """Callable that raises or returns the scripted outcomes in turn."""

    def __init__(self, *steps):
        self.steps = list(steps)
        self.calls = 0

    def __call__(self, *args):
        step = self.steps[min(self.calls, len(self.steps) - 1)]
        self.calls += 1
        if isinstance(step, Exception):
            raise step
        return step


class FakeProvider:
    def __init__(self, *steps):
        self.submit_script = Script(*steps)

    def submit(self, number, text):
        return self.submit_script(number, text)


class RetryTests(unittest.TestCase):
    def setUp(self):
        self.sleeps = []

    def run_retry(self, fn, **kw):
        return call_with_retry(fn, sleep=self.sleeps.append, rng=TopOfRange(), **kw)

    def test_success_needs_no_sleep(self):
        self.assertEqual(self.run_retry(Script("ok")), "ok")
        self.assertEqual(self.sleeps, [])

    def test_transient_errors_back_off_exponentially(self):
        fn = Script(GatewayTimeout("t"), GatewayTimeout("t"), GatewayTimeout("t"), "ok")
        self.assertEqual(self.run_retry(fn), "ok")
        self.assertEqual(self.sleeps, [0.5, 1.0, 2.0])

    def test_delay_is_capped(self):
        fn = Script(*[GatewayTimeout("t")] * 6, "ok")
        self.run_retry(fn, attempts=7, max_delay=3.0)
        self.assertEqual(self.sleeps, [0.5, 1.0, 2.0, 3.0, 3.0, 3.0])

    def test_gives_up_after_the_last_attempt_with_the_last_error(self):
        fn = Script(GatewayTimeout("first"), GatewayTimeout("second"))
        with self.assertRaises(GatewayTimeout) as ctx:
            self.run_retry(fn, attempts=2)
        self.assertEqual(str(ctx.exception), "second")
        self.assertEqual(fn.calls, 2)
        self.assertEqual(len(self.sleeps), 1)

    def test_rate_limit_waits_at_least_retry_after(self):
        fn = Script(RateLimited(5.0), "ok")
        self.run_retry(fn)
        self.assertEqual(self.sleeps, [5.0])

    def test_permanent_errors_are_not_retried(self):
        fn = Script(InvalidNumber("+1555"))
        with self.assertRaises(InvalidNumber):
            self.run_retry(fn)
        print("calls for a permanent error:", fn.calls, "sleeps:", self.sleeps)
        self.assertEqual(fn.calls, 1, "an invalid number can never succeed, so it must not be resubmitted")
        self.assertEqual(self.sleeps, [])

    def test_otp_to_an_invalid_number_costs_one_submission(self):
        provider = FakeProvider(InvalidNumber("+1555"))
        result = send_otp(SmsGateway(provider), "+1 (555) 000", "123456", sleep=self.sleeps.append, rng=TopOfRange())
        self.assertEqual((result.delivered, result.reason), (False, "invalid_number"))
        self.assertEqual(provider.submit_script.calls, 1)

    def test_otp_survives_a_timeout_and_cleans_the_number(self):
        provider = FakeProvider(GatewayTimeout("slow"), "msg-1")
        result = send_otp(SmsGateway(provider), "+1 (555) 010-2030", "123456", sleep=self.sleeps.append, rng=TopOfRange())
        self.assertEqual((result.delivered, result.attempts), (True, 2))


if __name__ == "__main__":
    unittest.main()
